import * as THREE from 'three';
import { terrainHeight } from './world';
import type { CombatSystem } from './combat';
import type { PlayerProgression } from './progression';

export type SpellId = 'zoltraak' | 'vollzanbel' | 'judradjim' | 'shield' | 'flight';
type Projectile = { object: THREE.Group; trail: THREE.Line; points: THREE.Vector3[]; velocity: THREE.Vector3; age: number; kind: 'zoltraak' | 'vollzanbel'; target: THREE.Vector3; damage: (at: THREE.Vector3, radius: number, amount: number) => void };
type Effect = { object: THREE.Group; age: number; life: number; ring?: THREE.Mesh; light?: THREE.PointLight; sparks?: { mesh: THREE.Mesh; velocity: THREE.Vector3 }[] };
const COST: Record<SpellId, number> = { zoltraak: 10, vollzanbel: 34, judradjim: 27, shield: 20, flight: 12 };
const COOLDOWN: Record<SpellId, number> = { zoltraak: .38, vollzanbel: 4.2, judradjim: 3.4, shield: 9, flight: .7 };

/** Shared spell registry, resource economy, projectile simulation and defensive collision. */
export class MagicSystem {
  mana = 100; readonly maxMana = 100; flying = false; shieldActive = false; shieldTime = 0; blocks = 0;
  private root = new THREE.Group(); private projectiles: Projectile[] = []; private effects: Effect[] = [];
  private cooldowns: Record<SpellId, number> = { zoltraak: 0, vollzanbel: 0, judradjim: 0, shield: 0, flight: 0 };
  private shieldRoot = new THREE.Group(); private shieldPanels: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>[] = []; private shieldFlash = 0;
  private readonly basicMat = new THREE.MeshBasicMaterial({ color: '#f3e5b8' });
  private readonly fireMat = new THREE.MeshBasicMaterial({ color: '#ff9a52' });
  private readonly trailMat = new THREE.LineBasicMaterial({ color: '#d9d8b3', transparent: true, opacity: .68 });
  private readonly fireTrailMat = new THREE.LineBasicMaterial({ color: '#e78c53', transparent: true, opacity: .55 });
  private readonly temp = new THREE.Object3D();
  private readonly collisionRay = new THREE.Raycaster();
  constructor(private scene: THREE.Scene, private player: THREE.Group, private combat: CombatSystem, private blockers: THREE.Object3D[], private progression: PlayerProgression) {
    this.root.name = 'spell-effects'; scene.add(this.root);
    this.shieldRoot.name = 'hex-aegis'; this.player.add(this.shieldRoot); this.shieldRoot.position.set(0, 1.28, .72);
    const panelGeo = new THREE.CircleGeometry(.49, 6); panelGeo.rotateZ(Math.PI / 6);
    for (let i = 0; i < 7; i++) {
      const mat = new THREE.ShaderMaterial({ transparent: true, depthWrite: false, side: THREE.DoubleSide, uniforms: { uTime: { value: 0 }, uFlash: { value: 0 } }, vertexShader: `varying vec2 vUv; varying vec3 vNormalView; void main(){vUv=uv;vNormalView=normalize(normalMatrix*normal);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`, fragmentShader: `uniform float uTime; uniform float uFlash; varying vec2 vUv; varying vec3 vNormalView; void main(){float edge=1.0-smoothstep(.84,.98,length((vUv-.5)*2.0));float scan=.5+.5*sin(vUv.y*34.0-uTime*2.2);float rim=pow(1.0-abs(vNormalView.z),2.0);float alpha=(.12+edge*.17+rim*.16+scan*.035+uFlash*.48)*edge;vec3 base=mix(vec3(.45,.67,.62),vec3(.88,.91,.76),uFlash*.7+rim*.25);gl_FragColor=vec4(base,alpha);}` });
      const panel = new THREE.Mesh(panelGeo, mat); panel.position.set(((i % 3) - 1) * .74, (Math.floor(i / 3) - 1) * .72, 0); panel.rotation.y = Math.PI; this.shieldRoot.add(panel); this.shieldPanels.push(panel);
      const edge = new THREE.Mesh(new THREE.EdgesGeometry(panelGeo), new THREE.LineBasicMaterial({ color: '#c3d7bc', transparent: true, opacity: .7 })); panel.add(edge);
    }
    this.shieldRoot.visible = false;
  }
  cooldown(id: SpellId) { return this.cooldowns[id]; }
  cast(id: SpellId, origin: THREE.Vector3, direction: THREE.Vector3, target: THREE.Vector3) {
    const manaCost = this.progression.manaCost(COST[id]);
    if (this.cooldowns[id] > 0 || this.mana < manaCost) return false;
    this.mana -= manaCost; this.cooldowns[id] = COOLDOWN[id];
    if (id === 'shield') { this.shieldActive = true; this.shieldTime = 6; this.shieldRoot.visible = true; this.shieldFlash = .45; return true; }
    if (id === 'flight') { this.flying = !this.flying; this.flightEffect(this.player.position); return true; }
    if (id === 'judradjim') { const size = this.progression.sizeMultiplier(); this.lightning(origin, target, size); this.combat.damageAt(target, 4.4 * size, 46 * this.progression.damageMultiplier()); return true; }
    const kind = id as 'zoltraak' | 'vollzanbel';
    const group = new THREE.Group(); group.name = kind; const fire = kind === 'vollzanbel';
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(fire ? .28 : .16, 2), fire ? this.fireMat : this.basicMat); core.scale.set(.82, .82, fire ? 1.5 : 1.8); group.add(core);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(fire ? .36 : .23, fire ? .04 : .025, 8, 24), new THREE.MeshBasicMaterial({ color: fire ? '#ffb05c' : '#d6c27e', transparent: true, opacity: .72 })); group.add(ring);
    group.add(new THREE.PointLight(fire ? '#ff8039' : '#ead7a2', fire ? 1.8 : 1.2, fire ? 6 : 4, 2));
    group.position.copy(origin).addScaledVector(direction, .5); group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), direction.clone().normalize()); group.scale.setScalar(this.progression.sizeMultiplier()); this.root.add(group);
    const points = Array.from({ length: 9 }, () => group.position.clone()); const geometry = new THREE.BufferGeometry().setFromPoints(points);
    const trail = new THREE.Line(geometry, fire ? this.fireTrailMat : this.trailMat); this.root.add(trail);
    this.projectiles.push({ object: group, trail, points, velocity: direction.clone().normalize().multiplyScalar(fire ? 13 : 34), age: 0, kind, target: target.clone(), damage: (p, radius, amount) => { const size = this.progression.sizeMultiplier(); this.combat.damageAt(p, radius * size, amount * this.progression.damageMultiplier()); } });
    this.flightEffect(origin); return true;
  }
  blockProjectile(from: THREE.Vector3, to: THREE.Vector3) {
    if (!this.shieldActive || this.mana <= 0) return false;
    const center = this.shieldRoot.getWorldPosition(new THREE.Vector3());
    const segment = new THREE.Line3(from, to); const closest = segment.closestPointToPoint(center, true, new THREE.Vector3());
    if (closest.distanceTo(center) > 1.38 * this.progression.sizeMultiplier()) return false;
    this.mana = Math.max(0, this.mana - 6); this.shieldTime = Math.max(0, this.shieldTime - .65); this.shieldFlash = .5; this.blocks++;
    this.impact(center, '#c7dfce', 1.6); return true;
  }
  update(delta: number, elapsed: number) {
    this.mana = Math.min(this.maxMana, this.mana + delta * (this.flying ? 1.2 : 4.2));
    for (const id of Object.keys(this.cooldowns) as SpellId[]) this.cooldowns[id] = Math.max(0, this.cooldowns[id] - delta);
    if (this.flying) { this.mana -= delta * 8; if (this.mana <= 0) { this.mana = 0; this.flying = false; this.flightEffect(this.player.position); } }
    if (this.shieldActive) { this.mana -= delta * 2.4; this.shieldTime -= delta; this.shieldRoot.visible = true; this.shieldRoot.scale.setScalar(this.progression.sizeMultiplier()); this.shieldRoot.rotation.y = Math.sin(elapsed * 1.1) * .055; }
    if (this.shieldActive && (this.shieldTime <= 0 || this.mana <= 0)) { this.shieldActive = false; this.shieldRoot.visible = false; }
    this.shieldFlash = Math.max(0, this.shieldFlash - delta * 2.4);
    this.shieldPanels.forEach((panel, i) => { panel.material.uniforms.uTime.value = elapsed + i * .22; panel.material.uniforms.uFlash.value = Math.max(0, this.shieldFlash + Math.sin(elapsed * 2.4 + i) * .015); });
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i], previous = p.object.position.clone(); p.age += delta; p.object.position.addScaledVector(p.velocity, delta); p.object.rotation.z += delta * 3;
      this.collisionRay.set(previous, p.velocity.clone().normalize()); this.collisionRay.near = 0; this.collisionRay.far = p.velocity.length() * delta + .12;
      const obstacle = this.collisionRay.intersectObjects(this.blockers, true)[0];
      if (obstacle) p.object.position.copy(obstacle.point);
      p.points.pop(); p.points.unshift(p.object.position.clone()); const attr = p.trail.geometry.attributes.position as THREE.BufferAttribute;
      p.points.forEach((v, j) => attr.setXYZ(j, v.x, v.y, v.z)); attr.needsUpdate = true; p.trail.geometry.computeBoundingSphere();
      const targetHit = p.object.position.distanceTo(p.target) < Math.max(.35, p.velocity.length() * delta);
      const enemyHit = this.combat.targets.some(target => { if (!target.visible) return false; target.updateMatrixWorld(); return new THREE.Box3().setFromObject(target).expandByScalar(.42).containsPoint(p.object.position); });
      const ground = p.object.position.y < terrainHeight(p.object.position.x, p.object.position.z) + .15;
      if (obstacle || enemyHit || targetHit || ground || p.age > (p.kind === 'vollzanbel' ? 2.5 : 1.35)) {
        const radius = p.kind === 'vollzanbel' ? 4.6 : .9; p.damage(p.object.position, radius, p.kind === 'vollzanbel' ? 58 : 34); this.impact(p.object.position, p.kind === 'vollzanbel' ? '#f28e4e' : '#eee1b5', p.kind === 'vollzanbel' ? 4.3 : 1.45);
        p.object.removeFromParent(); p.trail.removeFromParent(); p.object.traverse(o => { if (o instanceof THREE.Mesh) { o.geometry.dispose(); if (o.material !== this.basicMat && o.material !== this.fireMat) o.material.dispose(); } }); p.trail.geometry.dispose(); this.projectiles.splice(i, 1);
      }
    }
    for (let i = this.effects.length - 1; i >= 0; i--) { const e = this.effects[i]; e.age += delta; const t = Math.min(1, e.age / e.life); if (e.ring) { e.ring.scale.setScalar(.4 + t * 3); (e.ring.material as THREE.MeshBasicMaterial).opacity = (1 - t) * .78; } if (e.light) e.light.intensity = (1 - t) * 2.5; e.sparks?.forEach(({ mesh, velocity }) => { mesh.position.addScaledVector(velocity, delta); mesh.scale.setScalar(Math.max(.02, 1 - t)); }); if (t >= 1) { e.object.removeFromParent(); e.object.traverse(o => { if (o instanceof THREE.Mesh || o instanceof THREE.Line) { o.geometry.dispose(); if (Array.isArray(o.material)) o.material.forEach(m => m.dispose()); else o.material.dispose(); } }); this.effects.splice(i, 1); } }
  }
  dispose() { this.root.removeFromParent(); this.shieldRoot.removeFromParent(); this.projectiles.forEach(p => { p.trail.geometry.dispose(); }); this.effects.forEach(e => e.object.removeFromParent()); this.basicMat.dispose(); this.fireMat.dispose(); this.trailMat.dispose(); this.fireTrailMat.dispose(); }
  private impact(pos: THREE.Vector3, color: string, radius: number) { const g = new THREE.Group(); g.position.copy(pos); this.root.add(g); const m = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .8, side: THREE.DoubleSide, depthWrite: false }); const ring = new THREE.Mesh(new THREE.TorusGeometry(.65, .035, 7, 32), m); ring.rotation.x = -Math.PI / 2; g.add(ring); g.add(new THREE.PointLight(color, 2.5, radius * 2)); const geo = new THREE.OctahedronGeometry(.075, 0), pm = new THREE.MeshBasicMaterial({ color }), sparks: { mesh: THREE.Mesh; velocity: THREE.Vector3 }[] = []; for (let i = 0; i < 12; i++) { const particle = new THREE.Mesh(geo, pm); const a = i / 12 * Math.PI * 2; particle.position.set(Math.cos(a) * .5, .12 + (i % 3) * .1, Math.sin(a) * .5); g.add(particle); sparks.push({ mesh: particle, velocity: new THREE.Vector3(Math.cos(a), .4 + (i % 3) * .25, Math.sin(a)).multiplyScalar(2.1 + (i % 4) * .25) }); } this.effects.push({ object: g, age: 0, life: .52, ring, light: g.children.find(o => o instanceof THREE.PointLight) as THREE.PointLight, sparks }); }
  private lightning(from: THREE.Vector3, to: THREE.Vector3, size = 1) { const points: THREE.Vector3[] = [from.clone()]; const delta = to.clone().sub(from); for (let i = 1; i < 10; i++) points.push(from.clone().addScaledVector(delta, i / 10).add(new THREE.Vector3((Math.random() - .5) * .7 * size, (Math.random() - .5) * .6 * size, (Math.random() - .5) * .7 * size))); points.push(to.clone()); const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), new THREE.LineBasicMaterial({ color: '#d6dfc6', transparent: true, opacity: .95 })); this.root.add(line); const light = new THREE.PointLight('#cbdca9', 2.2, 9 * size); light.position.copy(to); this.root.add(light); this.effects.push({ object: new THREE.Group(), age: 0, life: .26 }); this.root.add(this.effects[this.effects.length - 1].object); this.effects[this.effects.length - 1].object.add(line, light); this.impact(to, '#d8e0c1', 3 * size); }
  private flightEffect(position: THREE.Vector3) { const g = new THREE.Group(); g.position.copy(position); this.root.add(g); const m = new THREE.MeshBasicMaterial({ color: '#c9d8b0', transparent: true, opacity: .65, side: THREE.DoubleSide }); const ring = new THREE.Mesh(new THREE.TorusGeometry(.62, .025, 7, 28), m); ring.rotation.x = Math.PI / 2; g.add(ring); this.effects.push({ object: g, age: 0, life: .5, ring }); }
}
